/* Œconomia — Entraînement : thème « Commerce international » (36 exercices, trois niveaux). */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");
  const lin = (a, b) => `${a} − ${b === 1 ? "" : b}P`;
  const linp = (c, d) => (c >= 0 ? `${c} + ${d === 1 ? "" : d}P` : `${d === 1 ? "" : d}P − ${-c}`);

  /* Marché d’un petit pays importateur : prix mondial, droit de douane (en francs), demande et offre intérieures linéaires */
  const genTarif = () => {
    const b = rnd(3, 6), d = rnd(2, 5), Pw = rnd(10, 18), t = pick([2, 3, 4]);
    const Pa = Pw + t + rnd(3, 8);                     /* prix d’autarcie, au-dessus du prix avec taxe */
    const Qa = rnd(150, 300);
    return { a: Qa + b * Pa, b, c: Qa - d * Pa, d, Pw, t };
  };
  const imports = (p, prix) => (p.a - p.b * prix) - (p.c + p.d * prix);
  /* Grand pays : l’offre des exportateurs étrangers (pente s = k × (b + d)) fait baisser le prix mondial quand le pays taxe */
  const grand = (p) => { const B = p.b + p.d, s = p.k * B, baisse = p.t / (1 + p.k), dp = p.t - baisse, P1 = p.Pw + dp, M0 = imports(p, p.Pw), M1 = imports(p, P1), tot = M1 * baisse, dwl = 0.5 * B * dp * dp; return { B, s, baisse, dp, P1, Pm: p.Pw - baisse, M0, M1, rec: p.t * M1, tot, dwl, net: tot - dwl }; };

  X.theme({ id: "commerce", nom: "Commerce international",
    intro: "Pourquoi les pays échangent-ils, qui y gagne et qui y perd, et que provoquent les droits de douane ? Ces exercices vous entraînent à calculer des avantages comparatifs, des soldes commerciaux et les effets d’un droit de douane, et à discuter du libre-échange et du protectionnisme.",
    notions: ["avantage-comparatif", "taux-de-change", "rendements-croissants", "division-travail", "institutions-inclusives", "surplus"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "co1-absolu-comparatif", theme: "commerce", niveau: 1, type: "qcm", notion: "avantage-comparatif",
    titre: "Avantage absolu et avantage comparatif", competence: "Distinguer les deux notions.",
    enonce: P("Une avocate tape son courrier deux fois plus vite que sa secrétaire. Pourtant, elle a intérêt à lui confier cette tâche. Pourquoi ?"),
    options: ["Parce que la secrétaire a un avantage absolu dans la frappe du courrier.","Parce que la secrétaire a un avantage comparatif dans la frappe.","Parce que la loi réserve la frappe du courrier au personnel de secrétariat.","Parce qu’il vaut toujours mieux confier le travail à quelqu’un d’autre."], c: 1, pourquoi: ["C’est l’avocate qui a l’avantage absolu, puisqu’elle tape plus vite. La secrétaire a un avantage comparatif.", null, "Aucune loi n’interdit à un avocat de taper son courrier : la raison est économique.", "Pas toujours : déléguer n’est avantageux que si l’autre a un coût d’opportunité plus faible pour cette tâche."],
    explication: P("L’avocate a un <b>avantage absolu</b> dans la frappe : elle est plus rapide. Mais chaque heure passée à taper l’empêche de plaider, ce qui lui rapporte beaucoup plus. Son <b>coût d’opportunité</b> pour la frappe est élevé ; celui de la secrétaire est faible. La secrétaire a donc un <b>avantage comparatif</b> dans la frappe.", "C’est le raisonnement de Ricardo appliqué aux pays : chacun gagne à se spécialiser là où il renonce au moins, même s’il est moins efficace en tout.") },

  { id: "co1-balance", theme: "commerce", niveau: 1, type: "calcul", notion: "avantage-comparatif",
    titre: "Le solde de la balance commerciale", competence: "Calculer un solde commercial et un taux de couverture.",
    gen: () => { let x, m; do { x = rnd(260, 420); m = rnd(230, 400); } while (x === m); return { x, m }; },
    enonce: (p) => P(`Un pays a exporté pour <b>${p.x} milliards</b> de francs de marchandises et importé pour <b>${p.m} milliards</b>.`, "Calculez le solde de la balance commerciale (signe moins en cas de déficit), puis le taux de couverture (exportations ÷ importations × 100), arrondi à une décimale."),
    champs: [{ label: "Solde", unite: "milliards", tol: 0.05 }, { label: "Taux de couverture", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.x - p.m, Math.round((p.x / p.m) * 1000) / 10],
    indice: "Solde = exportations − importations.",
    correction: (p) => P(`Solde = ${p.x} − ${p.m} = <b>${p.x - p.m} milliards</b> : ${p.x >= p.m ? "un excédent" : "un déficit"} commercial.`, `Taux de couverture = ${p.x} ÷ ${p.m} × 100 ≈ <b>${fmt(100 * p.x / p.m, 1)} %</b>.`, "Un excédent n’est pas forcément une « victoire » et un déficit pas forcément une faiblesse : un pays en forte croissance peut importer beaucoup de machines. La Suisse a des excédents commerciaux importants depuis longtemps.") },

  { id: "co1-cout-opp", theme: "commerce", niveau: 1, type: "calcul", notion: "avantage-comparatif",
    titre: "Le coût d’opportunité d’une production", competence: "Calculer ce à quoi on renonce en produisant un bien.",
    gen: () => { const m = rnd(2, 6), f = pick([2, 3, 4, 6, 8, 10, 12].filter((x) => x !== m)); return { m, f }; },
    enonce: (p) => P(`En une journée de travail, un atelier de menuiserie peut fabriquer soit <b>${p.m} tables</b>, soit <b>${p.f} chaises</b>.`, "Quel est le coût d’opportunité d’une table, exprimé en chaises ? Arrondissez à deux décimales."),
    champs: [{ label: "1 table =", unite: "chaises", tol: 0.01 }],
    reponses: (p) => [Math.round((p.f / p.m) * 100) / 100],
    indice: "Si l’atelier ne fabrique que des tables, à combien de chaises renonce-t-il ? Ramenez ce nombre à une seule table.",
    correction: (p) => P(`Une table demande 1/${p.m} de journée, pendant laquelle on aurait pu fabriquer ${p.f} ÷ ${p.m} chaises.`, `Coût d’opportunité d’une table = ${p.f} ÷ ${p.m} = <b>${fmt(p.f / p.m, 2)} chaises</b>.`, `Inversement, une chaise coûte ${fmt(p.m / p.f, 2)} table. L’entreprise ou le pays qui a le coût d’opportunité le plus faible pour un bien a l’avantage comparatif dans ce bien.`) },

  { id: "co1-vf-bases", theme: "commerce", niveau: 1, type: "vf", notion: "avantage-comparatif",
    titre: "Commerce international : les bases", competence: "Connaître le vocabulaire et quelques faits de base du commerce international.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Un droit de douane est un impôt prélevé sur les produits importés.", true, "Il renchérit les importations et protège les producteurs nationaux de la concurrence étrangère."],
      ["Le protectionnisme désigne l’ensemble des mesures qui favorisent les importations.", false, "C’est l’inverse : il regroupe les mesures qui <b>limitent</b> les importations pour protéger la production nationale (droits de douane, quotas, normes, subventions)."],
      ["L’essentiel du commerce mondial se fait entre pays très différents, qui échangent des produits très différents.", false, "Une grande partie du commerce se fait entre pays riches semblables, qui échangent des produits semblables : c’est le commerce intra-branche, expliqué par Krugman."],
      ["Quand la monnaie d’un pays s’apprécie, ses produits deviennent plus chers pour les acheteurs étrangers, toutes choses égales par ailleurs.", true, "Un même prix en monnaie nationale correspond à davantage de monnaie étrangère : les exportateurs ont plus de mal à vendre, alors que les importations deviennent moins chères."]
    ] },

  { id: "co1-douane", theme: "commerce", niveau: 1, type: "qcm", notion: "surplus",
    titre: "Qui paie un droit de douane ?", competence: "Prévoir l’effet d’un droit de douane pour les consommateurs.",
    enonce: P("Un pays impose un droit de douane de 25 % sur les vélos importés. Quel effet peut-on attendre pour les consommateurs de ce pays ?"),
    options: ["Les vélos deviennent moins chers, car les producteurs nationaux baissent leurs prix.", "Les vélos importés, et souvent aussi les vélos nationaux, deviennent plus chers.", "Rien ne change pour les consommateurs : ce sont les pays exportateurs qui paient.", "Les consommateurs reçoivent la recette du droit de douane."], c: 1, pourquoi: ["Protégés par le droit de douane, les producteurs nationaux subissent moins de concurrence : ils ont plutôt intérêt à monter leurs prix.", null, "Le droit est payé à la frontière par l’importateur, qui le répercute en grande partie sur le prix de vente : ce sont surtout les consommateurs du pays qui paient.", "La recette va à l’État, pas directement aux consommateurs."],
    explication: P("Le droit de douane renchérit les vélos importés. Protégés de la concurrence, les producteurs nationaux peuvent eux aussi augmenter leurs prix. Les <b>consommateurs</b> paient donc plus cher et achètent moins.", "Les producteurs nationaux et l’État, qui perçoit la taxe, y gagnent ; mais la perte des consommateurs est en général plus importante que ces gains.") },

  { id: "co1-mercantilisme", theme: "commerce", niveau: 1, type: "qcm", notion: "division-travail",
    titre: "La doctrine mercantiliste", competence: "Connaître une vision historique du commerce.",
    enonce: P("Au XVIIe siècle, Thomas Mun en Angleterre ou Colbert en France défendent le mercantilisme. Que pensent-ils du commerce extérieur ?"),
    options: ["Que l’échange enrichit tous les pays qui y participent, quel que soit leur solde.","Qu’un pays s’enrichit en exportant plus qu’il n’importe, pour accumuler de l’or.","Que l’État doit supprimer les droits de douane pour attirer les marchands étrangers.","Que la richesse vient avant tout de la terre et du travail des paysans."], c: 1, pourquoi: ["C’est la vision de Smith et de Ricardo, qui critiqueront le mercantilisme.", null, "Les mercantilistes défendent au contraire les droits de douane, pour protéger les manufactures et limiter les importations.", "C’est la thèse des physiocrates, comme Quesnay au XVIIIe siècle."],
    explication: P("Pour les mercantilistes, la richesse d’un État se mesure à son stock de métaux précieux. Il faut donc des <b>excédents commerciaux</b> : exporter des produits finis, importer peu, protéger les manufactures. Le commerce est vu comme une rivalité.", "Adam Smith et David Ricardo critiqueront cette vision : la richesse est ce qu’un pays produit, et l’échange peut enrichir tous les partenaires. La dernière réponse correspond aux physiocrates.") },

  { id: "co1-partenaires", theme: "commerce", niveau: 1, type: "qcm",
    titre: "Zone de libre-échange ou union douanière ?", competence: "Distinguer les formes d’intégration commerciale entre pays.",
    enonce: P("Plusieurs pays suppriment les droits de douane entre eux et appliquent un même droit de douane aux produits qui viennent du reste du monde. De quelle forme d’intégration s’agit-il ?"),
    options: ["D’une union douanière.", "D’une zone de libre-échange, où chaque pays garde ses propres droits envers l’extérieur.", "D’un cartel d’exportateurs.", "D’un régime de quotas réciproques."], c: 0, pourquoi: [null, "Dans une zone de libre-échange, les droits entre partenaires disparaissent, mais chaque pays fixe librement ses droits envers les pays tiers. Ici, le droit extérieur est commun.", "Un cartel est une entente entre entreprises pour fixer les prix ou les quantités. Il ne concerne pas la politique commerciale d’États.", "Un quota limite des quantités. Ici, les pays suppriment leurs droits entre eux et ne se limitent pas mutuellement."],
    explication: P("Dans une <b>union douanière</b>, les droits de douane disparaissent entre les membres et un <b>tarif extérieur commun</b> s’applique aux autres pays. C’est le cas de l’Union européenne.", "Dans une <b>zone de libre-échange</b>, comme celle de l’AELE ou celle que forment les États-Unis, le Mexique et le Canada, chaque pays garde sa propre politique envers l’extérieur. Il faut alors vérifier l’origine des produits à la frontière, pour éviter qu’ils n’entrent par le pays aux droits les plus bas.") },

  { id: "co1-exports", theme: "commerce", niveau: 1, type: "document", notion: "avantage-comparatif",
    titre: "Que vend la Suisse au monde ?", competence: "Lire la structure des exportations d’un pays.",
    enonce: P("Part approximative des principales branches dans les exportations suisses de marchandises (années 2020, valeurs arrondies, hors or) :") +
      `<table><thead><tr><th>Branche</th><th>Part</th></tr></thead><tbody><tr><td>Chimie et pharmacie</td><td>environ 50 %</td></tr><tr><td>Machines et électronique</td><td>environ 12 %</td></tr><tr><td>Horlogerie</td><td>environ 9 %</td></tr><tr><td>Instruments de précision</td><td>environ 7 %</td></tr><tr><td>Autres</td><td>environ 22 %</td></tr></tbody></table><p class="ex-source">Source : Office fédéral de la douane et de la sécurité des frontières (OFDF), statistique du commerce extérieur ; parts arrondies, années 2020, hors or.</p>` +
      P("Quelle conclusion est la plus juste ?"),
    options: ["La Suisse exporte surtout des matières premières et des produits agricoles bruts.", "La Suisse s’est spécialisée dans des produits transformés à forte valeur ajoutée.", "L’horlogerie est la première branche exportatrice de la Suisse, devant la chimie et les machines.", "La Suisse n’a pas d’avantage comparatif, puisqu’elle importe aussi beaucoup de biens."], c: 1, pourquoi: ["La Suisse a peu de matières premières : elle exporte surtout des produits transformés, d’abord chimiques et pharmaceutiques.", null, "L’horlogerie pèse environ 9 % ; la chimie et la pharmacie, environ 50 %, la devancent largement.", "Une spécialisation aussi nette révèle au contraire des avantages comparatifs. Importer beaucoup n’empêche pas d’en avoir."],
    explication: P("La chimie et la pharmacie, les machines, l’horlogerie et les instruments de précision sont des produits qui demandent beaucoup de <b>capital humain</b> et d’innovation. La Suisse, pauvre en ressources naturelles mais riche en main-d’œuvre qualifiée et en recherche, a un avantage comparatif dans ces productions, comme le prévoit la théorie de Heckscher et Ohlin.", "Cette concentration sur la pharmacie rend aussi la Suisse sensible aux décisions de quelques grandes entreprises et aux politiques commerciales de ses clients.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "co2-ricardo", theme: "commerce", niveau: 2, type: "calcul", notion: "avantage-comparatif",
    titre: "Trouver l’avantage comparatif", competence: "Calculer et comparer des coûts d’opportunité entre deux pays.",
    gen: () => { let a1, a2, b1, b2; do { a1 = rnd(2, 8); a2 = rnd(2, 8); b1 = rnd(2, 8); b2 = rnd(2, 8); } while (Math.abs(a1 / a2 - b1 / b2) < 0.15 || a1 === b1 || a2 === b2); return { a1, a2, b1, b2 }; },
    enonce: (p) => P("Heures de travail nécessaires pour produire une unité :") +
      `<table><thead><tr><th></th><th>Chocolat (1 kg)</th><th>Logiciel (1 licence)</th></tr></thead><tbody><tr><td>Pays A</td><td>${p.a1} h</td><td>${p.a2} h</td></tr><tr><td>Pays B</td><td>${p.b1} h</td><td>${p.b2} h</td></tr></tbody></table><p class="ex-source">Données tirées au hasard pour l’exercice.</p>` +
      P("Calculez, pour chaque pays, le coût d’opportunité d’un kilo de chocolat en licences de logiciel (arrondi à deux décimales). Le pays dont le coût est le plus faible a l’avantage comparatif dans le chocolat."),
    champs: [{ label: "Pays A", unite: "licence(s)", tol: 0.01 }, { label: "Pays B", unite: "licence(s)", tol: 0.01 }],
    reponses: (p) => [Math.round((p.a1 / p.a2) * 100) / 100, Math.round((p.b1 / p.b2) * 100) / 100],
    indice: "Coût d’opportunité du chocolat = heures pour le chocolat ÷ heures pour un logiciel.",
    correction: (p) => { const ca = p.a1 / p.a2, cb = p.b1 / p.b2, A = ca < cb; return P(`Pays A : ${p.a1} ÷ ${p.a2} ; pays B : ${p.b1} ÷ ${p.b2}.`, `Coûts d’opportunité : pays A = <b>${fmt(ca, 2)}</b> licence ; pays B = <b>${fmt(cb, 2)}</b> licence.`, `Le pays <b>${A ? "A" : "B"}</b> renonce à moins de logiciels pour produire du chocolat : il a l’avantage comparatif dans le chocolat ; l’autre pays l’a dans les logiciels.`, (p.a1 < p.b1 && p.a2 < p.b2) || (p.a1 > p.b1 && p.a2 > p.b2) ? `Remarquez qu’un des deux pays est plus productif pour les deux biens (avantage absolu), et pourtant l’échange profite aux deux : c’est le résultat de Ricardo.` : `Ici, chaque pays a aussi un avantage absolu dans un bien différent.`); } },

  { id: "co2-termes", theme: "commerce", niveau: 2, type: "calcul", notion: "avantage-comparatif",
    titre: "À quel prix échanger ?", competence: "Déterminer l’intervalle des termes de l’échange mutuellement avantageux.",
    gen: () => { const pairs = [[1, 2], [2, 3], [3, 4], [1, 3], [2, 5], [3, 5]]; const [x, y] = pick(pairs); const k = pick([1, 2]); return { lo: x * k / (y * k), hi: (y + x) / y, x, y, q: pick([0.25, 0.5, 0.75]) }; },
    enonce: (p) => P(`Au Portugal, il faut <b>${p.x} heure${p.x > 1 ? "s" : ""}</b> de travail pour produire un tonneau de vin et <b>${p.y} heures</b> pour une pièce de drap. En Angleterre, il faut <b>${p.x + p.y} heures</b> pour le tonneau de vin et <b>${p.y} heures</b> pour la pièce de drap.`, "Le Portugal se spécialise dans le vin, l’Angleterre dans le drap. Entre quelles limites doit se situer le prix d’un tonneau de vin, exprimé en pièces de drap, pour que l’échange profite aux deux pays ? Arrondissez à deux décimales.", `Les deux pays concluent ensuite l’échange à un prix de <b>${fmt(X.arr(p.lo, 2) + p.q, 2)} pièce de drap</b> par tonneau. Quelle part du gain total de l’échange revient au Portugal ? Le gain de chaque pays se mesure par tonneau, en pièces de drap, par rapport à ce qu’il obtiendrait sans échanger.`),
    champs: [{ label: "Prix minimal", unite: "drap", tol: 0.01 }, { label: "Prix maximal", unite: "drap", tol: 0.01 }, { label: "Part du Portugal", unite: "%", tol: 1 }],
    reponses: (p) => [X.arr(p.lo, 2), X.arr(p.hi, 2), 100 * p.q],
    indice: "Calculez d’abord, pour chaque pays, le coût d’opportunité d’un tonneau de vin en pièces de drap. Le vendeur n’accepte pas moins que son coût, l’acheteur ne paie pas plus que le sien.",
    correction: (p) => P(`Coût d’opportunité d’un tonneau au Portugal, ${p.x} ÷ ${p.y} = ${fmt(p.lo, 2)} pièce de drap. En Angleterre, ${p.x + p.y} ÷ ${p.y} = ${fmt(p.hi, 2)}.`, `Le Portugal vend son vin seulement s’il reçoit au moins ce qu’il lui coûte : <b>${fmt(p.lo, 2)}</b> drap par tonneau.`, `L’Angleterre l’achète seulement si c’est moins cher que de le produire elle-même : au plus <b>${fmt(p.hi, 2)}</b> drap par tonneau.`, `Au prix de ${fmt(X.arr(p.lo, 2) + p.q, 2)}, le Portugal gagne ${fmt(p.q, 2)} drap par tonneau (il obtient ${fmt(X.arr(p.lo, 2) + p.q, 2)} au lieu de ${fmt(X.arr(p.lo, 2), 2)}) et l’Angleterre ${fmt(1 - p.q, 2)} (elle paie ${fmt(X.arr(p.lo, 2) + p.q, 2)} au lieu de ${fmt(X.arr(p.hi, 2), 2)}). Le gain total est de 1 drap par tonneau, et la part du Portugal est <b>${fmt(100 * p.q, 0)} %</b>.`, "Tout prix compris entre ces deux limites fait gagner les deux pays. Le prix exact, appelé <b>termes de l’échange</b>, dépend de la demande de chaque pays et détermine comment le gain est partagé.") },

  { id: "co2-ho", theme: "commerce", niveau: 2, type: "qcm", notion: "avantage-comparatif",
    titre: "Le modèle de Heckscher-Ohlin", competence: "Appliquer le modèle de Heckscher et Ohlin à deux pays dotés différemment.",
    enonce: P("Deux pays disposent des ressources suivantes. Ils peuvent fabriquer des machines, qui demandent beaucoup de capital par travailleur, et des vêtements, qui demandent peu de capital par travailleur. Leurs techniques sont identiques.") +
      `<table><thead><tr><th></th><th>Capital</th><th>Travail</th></tr></thead><tbody><tr><td>Pays Nord</td><td>60</td><td>40</td></tr><tr><td>Pays Sud</td><td>20</td><td>80</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Ils ouvrent leurs frontières. Que prévoit le modèle de Heckscher et Ohlin ?"),
    options: ["Le Nord exporte des machines et le Sud des vêtements, car chacun exporte le bien qui utilise le facteur dont il est le mieux doté.", "Le Nord exporte des vêtements et le Sud des machines, car le facteur rare est rémunéré plus cher et donne un avantage.", "Le Nord exporte les deux biens, car il possède plus de capital que le Sud en valeur absolue.", "Aucun échange n’a lieu, car les deux pays utilisent les mêmes techniques et n’ont donc rien à s’échanger."], c: 0, pourquoi: [null, "C’est l’inverse. Le facteur rare est cher, ce qui renchérit les biens qui l’utilisent beaucoup : le Nord a un avantage pour les machines, qui demandent du capital.", "Le raisonnement compare les dotations relatives. Le Nord a 1,5 unité de capital par travailleur et le Sud 0,25 : le Nord est relativement riche en capital, et le Sud ne reste pas sans production.", "Avec des techniques identiques, ce sont les dotations qui créent la différence de coûts relatifs, donc l’échange. C’est le cœur du modèle."],
    explication: P("Le Nord dispose de 1,5 unité de capital par travailleur, le Sud de 0,25. Le Nord est <b>relativement riche en capital</b>, le Sud en travail. Chaque pays exporte le bien qui utilise intensivement son facteur abondant : le Nord les machines, le Sud les vêtements.", "Le modèle compare des dotations relatives, pas des quantités absolues, et suppose les mêmes techniques dans les deux pays. Le théorème de Stolper et Samuelson en tire une conséquence : au Nord, l’ouverture profite au capital et pèse sur le travail.", "Le test empirique de Leontief sur les États-Unis des années 1950 a donné un résultat contraire à cette prévision, le « paradoxe de Leontief », ce qui a conduit à tenir compte des différences de qualification et de technologie.") },

  { id: "co2-tarif-effets", theme: "commerce", niveau: 2, type: "qcm", notion: "surplus",
    titre: "Le bilan d’un droit de douane", competence: "Identifier les gagnants et les perdants d’un droit de douane.",
    enonce: P("Un petit pays, qui ne peut pas influencer les prix mondiaux, impose un droit de douane sur l’acier importé. Quel bilan l’analyse économique standard en tire-t-elle pour ce pays ?"),
    options: ["Tout le monde y gagne, producteurs, consommateurs et État, grâce à la protection.","Producteurs et État y gagnent, mais les consommateurs perdent davantage.","Seuls les pays exportateurs y perdent, le pays qui impose le droit n’y perd rien.","Les consommateurs y gagnent, car la concurrence nationale fait baisser les prix."], c: 1, pourquoi: ["Les consommateurs paient plus cher et achètent moins : ils y perdent, et leur perte dépasse les gains des autres.", null, "Les consommateurs du pays qui impose le droit de douane y perdent aussi, et le pays dans son ensemble subit une perte sèche.", "Le droit de douane réduit la concurrence étrangère : le prix intérieur monte, il ne baisse pas."],
    explication: P("Le droit de douane fait monter le prix intérieur. Les <b>producteurs nationaux</b> vendent plus cher et produisent davantage : ils y gagnent. L’<b>État</b> perçoit la taxe sur les importations restantes. Les <b>consommateurs</b> paient plus cher et achètent moins : ils y perdent.", "La perte des consommateurs dépasse la somme des gains : la différence est la <b>perte sèche</b>, due à une production nationale plus coûteuse et à des achats qui n’ont plus lieu. Pour un grand pays, qui peut faire baisser le prix mondial, le bilan peut être différent.") },

  { id: "co2-importations", theme: "commerce", niveau: 2, type: "calcul", notion: "surplus",
    titre: "L’effet d’un droit de douane sur les importations", competence: "Calculer les importations avant et après un droit de douane.",
    gen: genTarif,
    enonce: (p) => P(`Dans un petit pays, la demande et l’offre intérieures de fromage à raclette (en tonnes) sont : <b>Q<sub>d</sub> = ${lin(p.a, p.b)}</b> et <b>Q<sub>o</sub> = ${linp(p.c, p.d)}</b> (P en francs par kilo).`, `Le prix mondial est de <b>${p.Pw} francs</b>. Le pays importe ce qui manque à ce prix. Il instaure ensuite un droit de douane de <b>${p.t} francs par kilo</b>.`, "Calculez les importations avant et après le droit de douane."),
    champs: [{ label: "Importations avant", unite: "t", tol: 0.5 }, { label: "Importations après", unite: "t", tol: 0.5 }],
    reponses: (p) => [imports(p, p.Pw), imports(p, p.Pw + p.t)],
    indice: "Importations = quantité demandée − quantité offerte, au prix en vigueur (prix mondial, puis prix mondial + droit de douane).",
    correction: (p) => { const P1 = p.Pw + p.t; return P(`Avant : Q<sub>d</sub> = ${p.a} − ${p.b} × ${p.Pw} = ${p.a - p.b * p.Pw} ; Q<sub>o</sub> = ${p.c} + ${p.d} × ${p.Pw} = ${p.c + p.d * p.Pw}. Importations = <b>${imports(p, p.Pw)} t</b>.`, `Après, au prix de ${P1} francs : Q<sub>d</sub> = ${p.a - p.b * P1} ; Q<sub>o</sub> = ${p.c + p.d * P1}. Importations = <b>${imports(p, P1)} t</b>.`, `Les importations baissent de ${imports(p, p.Pw) - imports(p, P1)} tonnes : la production nationale augmente de ${p.d * p.t} t et la consommation diminue de ${p.b * p.t} t.`); } },

  { id: "co2-vf-gagnants", theme: "commerce", niveau: 2, type: "vf", notion: "avantage-comparatif",
    titre: "Gagnants et perdants de la mondialisation", competence: "Connaître les effets répartitifs du commerce.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Les travaux sur le « choc chinois » ont montré que les pertes d’emplois industriels aux États-Unis étaient réparties de façon uniforme sur tout le territoire.", false, "Elles ont été <b>concentrées</b> dans certaines régions, durables et mal compensées, selon David Autor, David Dorn et Gordon Hanson."],
      ["Selon la théorie, l’ouverture au commerce augmente le revenu total d’un pays, mais peut faire des perdants.", true, "Le gain d’ensemble permettrait en principe de compenser les perdants, mais cette compensation n’a souvent pas eu lieu."],
      ["Les consommateurs des pays riches ont bénéficié de la baisse des prix de nombreux produits importés.", true, "Vêtements, électronique et jouets sont devenus beaucoup moins chers, ce qui a surtout profité aux ménages modestes, qui y consacrent une part importante de leur budget."],
      ["Le théorème de Stolper-Samuelson prédit que l’ouverture profite au facteur de production rare dans le pays.", false, "Il prédit l’inverse : l’ouverture profite au facteur <b>abondant</b> et pèse sur le facteur rare."]
    ] },

  { id: "co2-agriculture", theme: "commerce", niveau: 2, type: "redaction", notion: "surplus",
    titre: "Faut-il protéger l’agriculture suisse ?", competence: "Argumenter sur une politique commerciale.",
    enonce: P("La Suisse a supprimé ses droits de douane sur les produits industriels en 2024, mais son agriculture reste l’une des plus protégées du monde, par des droits de douane élevés et des paiements directs aux paysans.", "<b>Consigne :</b> présentez des arguments en faveur et contre cette protection. Nommez au moins une notion d’économie (avantage comparatif, prix, surplus, externalité, bien public) et expliquez-la en une phrase. Distinguez ces deux instruments. Concluez par une prise de position explicite. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse présente au moins deux arguments en faveur : sécurité de l’approvisionnement, entretien des paysages et des régions de montagne, qualité et normes, emplois agricoles, tourisme…", "Elle présente au moins deux arguments contre : prix plus élevés pour les consommateurs, coût pour les contribuables, perte sèche, entrave aux accords de libre-échange, absence d’avantage comparatif…", "Elle nomme au moins une notion d’économie et l’explique en une phrase (par exemple, un droit de douane fait payer plus cher les consommateurs).", "Elle distingue les deux instruments, les droits de douane, payés par les consommateurs, et les paiements directs, payés par les contribuables.", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Pour :</b> l’agriculture ne produit pas seulement des aliments. Elle entretient les paysages, maintient la vie dans les régions de montagne et contribue au tourisme : ce sont des <b>externalités positives</b> et des <b>biens publics</b> que le marché ne rémunère pas. La protection assure aussi une part d’approvisionnement national en cas de crise, et le respect de normes élevées en matière de bien-être animal et d’environnement.", "<b>Contre :</b> la Suisse n’a pas d’<b>avantage comparatif</b> dans la plupart des productions agricoles, en raison du relief, du climat et de salaires élevés. Les droits de douane font payer aux consommateurs des prix bien plus élevés qu’à l’étranger, entraînent une perte sèche, et compliquent la conclusion d’accords de libre-échange avec de grands pays agricoles.", "<b>Conclusion :</b> soutenir les prestations utiles à toute la société, comme l’entretien des paysages, par des paiements directs ciblés est plus efficace que de protéger les prix par des droits de douane, qui pèsent surtout sur les ménages modestes.") },

  { id: "co2-intra", theme: "commerce", niveau: 2, type: "qcm", notion: "rendements-croissants",
    titre: "Des voitures contre des voitures", competence: "Expliquer le commerce intra-branche.",
    enonce: P("L’Allemagne vend des voitures à la France, et la France vend des voitures à l’Allemagne. Comment Paul Krugman explique-t-il ce commerce entre pays semblables ?"),
    options: ["Par l’avantage comparatif, chaque pays produisant les voitures où il est le plus efficace.","Par les rendements croissants et le goût des consommateurs pour la variété.","Par les différences de dotations en capital et en travail entre les deux pays.","Par des droits de douane élevés, qui poussent chaque pays à acheter chez l’autre."], c: 1, pourquoi: ["L’avantage comparatif explique le commerce entre pays différents, pas l’échange de produits semblables entre pays semblables.", null, "Les deux pays ont des dotations en facteurs proches : le modèle de Heckscher et Ohlin n’explique pas ce commerce entre pays semblables.", "Il n’y a pas de droits de douane entre la France et l’Allemagne, membres de l’Union européenne : ils freineraient d’ailleurs ce commerce."],
    explication: P("Quand la production bénéficie de <b>rendements croissants</b>, produire en grande série réduit les coûts : chaque constructeur se concentre sur quelques modèles. Comme les consommateurs aiment la <b>variété</b>, chaque pays exporte certains modèles et importe les autres.", "Ce commerce <b>intra-branche</b>, qui domine les échanges entre pays riches, fait moins de perdants que le commerce entre pays très différents, car il ne supprime pas des branches entières.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "co3-recette-perte", theme: "commerce", niveau: 3, type: "calcul", notion: "surplus",
    titre: "Un grand pays peut-il gagner à taxer ses importations ?", competence: "Établir le nouvel équilibre d’un grand pays qui taxe ses importations, puis comparer le gain de termes de l’échange à la perte sèche.",
    gen: () => { let p; do { const b = rnd(3, 6), d = rnd(2, 5), Pw = rnd(10, 18), t = pick([2, 4, 6]), k = pick([1, 3]), Pa = Pw + t + rnd(3, 8), Qa = rnd(150, 300); p = { a: Qa + b * Pa, b, c: Qa - d * Pa, d, Pw, t, k }; } while (Math.abs(grand(p).net) < 1); return p; },
    enonce: (p) => { const g = grand(p); return P(`Un pays assez grand pour peser sur le prix mondial a pour demande et offre intérieures <b>Q<sub>d</sub> = ${lin(p.a, p.b)}</b> et <b>Q<sub>o</sub> = ${linp(p.c, p.d)}</b> (P en francs, quantités en milliers d’unités). En libre-échange, le prix mondial est de <b>${p.Pw} francs</b>.`, `Les exportateurs étrangers offrent alors exactement ce que le pays importe à ce prix. Chaque franc de hausse du prix mondial les pousse à offrir <b>${g.s} milliers d’unités</b> de plus, et chaque franc de baisse à en offrir autant de moins.`, `Le pays instaure un droit de douane de <b>${p.t} francs</b> par unité. Le prix intérieur devient le prix mondial augmenté du droit. Établissez l’égalité entre les importations du pays et l’offre des exportateurs étrangers, puis calculez le prix mondial après le droit (deux décimales), la recette de l’État, le gain de termes de l’échange (économie réalisée sur les importations restantes grâce à la baisse du prix mondial), la perte sèche (les deux triangles, calculés par rapport au libre-échange), et dites si le pays y gagne au total.`); },
    champs: [{ label: "Prix mondial après le droit", unite: "fr.", tol: 0.02 }, { label: "Recette", unite: "milliers de fr.", tol: 0.5 }, { label: "Gain de termes de l’échange", unite: "milliers de fr.", tol: 0.5 }, { label: "Perte sèche", unite: "milliers de fr.", tol: 0.5 }, { label: "Le pays y gagne-t-il au total ?", choix: ["oui", "non"] }],
    reponses: (p) => { const g = grand(p); return [X.arr(g.Pm, 2), X.arr(g.rec, 2), X.arr(g.tot, 2), X.arr(g.dwl, 2), g.net > 0 ? 0 : 1]; },
    indice: "Notez P* le prix mondial après le droit. Le prix intérieur est P* + droit, et les importations valent Q<sub>d</sub> − Q<sub>o</sub> à ce prix. Elles doivent égaler l’offre étrangère, qui varie avec P* autour du point de libre-échange.",
    correction: (p) => { const g = grand(p), x = p.t / (1 + p.k); return P(`Importations en libre-échange : (${p.a} − ${p.b} × ${p.Pw}) − (${p.c} + ${p.d} × ${p.Pw}) = <b>${g.M0}</b>. Elles se réduisent de ${p.b} + ${p.d} = ${g.B} unités par franc de hausse du prix intérieur.`, `Égalité d’équilibre, avec P* = ${p.Pw} − x : importations = ${g.M0} − ${g.B} × (t − x) et offre étrangère = ${g.M0} − ${g.s} × x. Donc ${g.B} × (${p.t} − x) = ${g.s} x, soit x = ${p.t} × ${g.B} ÷ (${g.B} + ${g.s}) = ${fmt(x, 2)}.`, `Prix mondial après le droit = ${p.Pw} − ${fmt(x, 2)} = <b>${fmt(g.Pm, 2)} francs</b>. Le prix intérieur monte à ${fmt(g.P1, 2)} francs, de ${fmt(g.dp, 2)} franc${g.dp >= 2 ? "s" : ""} seulement.`, `Importations après : ${g.M0} − ${g.B} × ${fmt(g.dp, 2)} = ${fmt(g.M1, 2)}. Recette = ${p.t} × ${fmt(g.M1, 2)} = <b>${fmt(g.rec, 2)} milliers de francs</b>.`, `Gain de termes de l’échange = ${fmt(g.M1, 2)} × ${fmt(x, 2)} = <b>${fmt(g.tot, 2)}</b>. Perte sèche = ½ × ${fmt(g.dp, 2)} × (${p.d} + ${p.b}) × ${fmt(g.dp, 2)} = <b>${fmt(g.dwl, 2)}</b>.`, g.net > 0 ? `Le gain dépasse la perte sèche de ${fmt(g.net, 2)} : le pays y gagne, aux dépens de ses fournisseurs.` : `La perte sèche dépasse le gain de ${fmt(-g.net, 2)} : le pays y perd, car l’offre étrangère réagit assez au prix pour que le droit ne fasse baisser que faiblement le prix mondial.`, "C’est l’argument du droit de douane optimal : un grand pays peut reporter une partie du droit sur ses fournisseurs. Plus l’offre étrangère est sensible au prix, plus ce pouvoir s’efface, et l’on retrouve le cas du petit pays, où le droit coûte toujours. Le gain suppose en outre que les partenaires ne ripostent pas."); } },

  { id: "co3-change", theme: "commerce", niveau: 3, type: "calcul", notion: "taux-de-change",
    titre: "Une dépréciation améliore-t-elle le solde commercial ?", competence: "Évaluer l’effet d’une dépréciation sur le solde commercial et tester la condition de Marshall-Lerner.",
    gen: () => { let p; do { p = { V: pick([200, 250, 300, 400]), d: pick([5, 8, 10]), ex: pick([0.2, 0.3, 0.4, 0.8, 1.1]), em: pick([0.2, 0.3, 0.4, 0.5, 0.7]) }; } while (Math.abs(p.ex + p.em - 1) < 0.2); return p; },
    enonce: (p) => P(`Un pays échange chaque année pour <b>${p.V} milliards</b> de biens avec l’étranger : ses exportations et ses importations s’équilibrent. Sa monnaie se déprécie. Les produits importés renchérissent de <b>${p.d} %</b> en monnaie nationale, et les produits exportés deviennent <b>${p.d} %</b> moins chers pour les clients étrangers. Le prix des exportations en monnaie nationale ne change pas, et celui des importations en monnaie étrangère non plus.`, `Le volume des exportations augmente de <b>${fmt(p.ex)} %</b> pour chaque pour cent de baisse de leur prix à l’étranger. Le volume des importations diminue de <b>${fmt(p.em)} %</b> pour chaque pour cent de hausse de leur prix. Calculez la valeur des exportations et celle des importations après la dépréciation (en monnaie nationale, deux décimales), la variation du solde commercial (signe moins pour une baisse), puis dites si la condition de Marshall-Lerner (somme des deux élasticités supérieure à 1) est remplie.`),
    champs: [{ label: "Exportations après", unite: "milliards", tol: 0.5 }, { label: "Importations après", unite: "milliards", tol: 0.5 }, { label: "Variation du solde", unite: "milliards", tol: 0.5 }, { label: "Marshall-Lerner remplie ?", choix: ["oui", "non"] }],
    reponses: (p) => { const x = p.V * (1 + p.ex * p.d / 100), m = p.V * (1 + p.d / 100) * (1 - p.em * p.d / 100); return [X.arr(x, 2), X.arr(m, 2), X.arr(x - m, 2), p.ex + p.em > 1 ? 0 : 1]; },
    indice: "Les exportations gardent leur prix en monnaie nationale : seule leur quantité change. Pour les importations, la valeur est le prix, qui monte, fois la quantité, qui baisse.",
    correction: (p) => { const x = p.V * (1 + p.ex * p.d / 100), m = p.V * (1 + p.d / 100) * (1 - p.em * p.d / 100), s = p.ex + p.em; return P(`Exportations : volume en hausse de ${fmt(p.ex)} × ${p.d} = ${fmt(p.ex * p.d, 1)} %, prix inchangé. Valeur = ${p.V} × ${fmt(1 + p.ex * p.d / 100, 4)} = <b>${fmt(x, 2)} milliards</b>.`, `Importations : prix en hausse de ${p.d} %, volume en baisse de ${fmt(p.em)} × ${p.d} = ${fmt(p.em * p.d, 1)} %. Valeur = ${p.V} × ${fmt(1 + p.d / 100, 2)} × ${fmt(1 - p.em * p.d / 100, 4)} = <b>${fmt(m, 2)} milliards</b>.`, `Variation du solde = ${fmt(x, 2)} − ${fmt(m, 2)} = <b>${fmt(x - m, 2)} milliard${Math.abs(x - m) >= 2 ? "s" : ""}</b>.`, `Somme des élasticités = ${fmt(p.ex)} + ${fmt(p.em)} = ${fmt(s)} : la condition de Marshall-Lerner est <b>${s > 1 ? "remplie" : "non remplie"}</b>. ${s > 1 ? "L’effet sur les quantités l’emporte sur le renchérissement des importations, et la dépréciation améliore le solde." : "Les quantités réagissent trop peu : le renchérissement des importations pèse plus que le gain à l’exportation, et le solde se dégrade."}`, "Les élasticités sont souvent faibles à court terme, car les contrats sont déjà signés et les habitudes d’achat changent lentement. Le solde peut donc d’abord se dégrader, puis s’améliorer quand les quantités s’ajustent : c’est la courbe en J. Pour une appréciation de la monnaie, le raisonnement s’inverse."); } },

  { id: "co3-termes-indice", theme: "commerce", niveau: 3, type: "calcul", notion: "avantage-comparatif",
    titre: "Les termes de l’échange et le pouvoir d’achat des exportations", competence: "Déduire des indices de prix des valeurs et des volumes, puis distinguer les termes de l’échange du pouvoir d’achat des exportations.",
    gen: () => { let p; do { const px = pick([85, 90, 95, 105, 115, 125]), qx = pick([96, 100, 104, 108, 112]), pm = pick([98, 102, 106, 110]), qm = pick([100, 105, 110, 115]); p = { px, qx, pm, qm, vx: px * qx / 100, vm: pm * qm / 100 }; } while (Math.abs(100 * p.px / p.pm - 100) < 1 || Math.abs(p.px / p.pm * p.qx - 100) < 1); return p; },
    enonce: (p) => P(`Par rapport à l’année de base (indices 100), un pays exportateur de cuivre enregistre cette année une valeur des exportations de <b>${fmt(p.vx, 1)}</b> pour un volume de <b>${p.qx}</b>, et une valeur des importations de <b>${fmt(p.vm, 1)}</b> pour un volume de <b>${p.qm}</b>.`, "Déduisez-en les indices de prix des exportations et des importations, puis les termes de l’échange (prix des exportations ÷ prix des importations × 100) et le pouvoir d’achat des exportations (termes de l’échange × volume des exportations ÷ 100), à une décimale. Dites enfin si ce pouvoir d’achat a augmenté ou diminué par rapport à l’année de base."),
    champs: [{ label: "Prix des exportations", unite: "", tol: 0.15 }, { label: "Prix des importations", unite: "", tol: 0.15 }, { label: "Termes de l’échange", unite: "", tol: 0.2 }, { label: "Pouvoir d’achat des exportations", unite: "", tol: 0.3 }, { label: "Il a…", choix: ["augmenté", "diminué"] }],
    reponses: (p) => { const t = 100 * p.px / p.pm; return [p.px, p.pm, X.arr(t, 1), X.arr(t * p.qx / 100, 1), t * p.qx / 100 > 100 ? 0 : 1]; },
    indice: "Une valeur est un prix multiplié par un volume : en indices, valeur = prix × volume ÷ 100. Le pouvoir d’achat des exportations mesure ce que l’on peut importer avec ce que l’on exporte.",
    correction: (p) => { const t = 100 * p.px / p.pm, pa = t * p.qx / 100; return P(`Prix des exportations = ${fmt(p.vx, 1)} ÷ ${p.qx} × 100 = <b>${p.px}</b>. Prix des importations = ${fmt(p.vm, 1)} ÷ ${p.qm} × 100 = <b>${p.pm}</b>.`, `Termes de l’échange = ${p.px} ÷ ${p.pm} × 100 ≈ <b>${fmt(t, 1)}</b>${t > 100 ? " : ils se sont améliorés" : " : ils se sont détériorés"}.`, `Pouvoir d’achat des exportations = termes × ${p.qx} ÷ 100 = ${p.px} ÷ ${p.pm} × ${p.qx} ≈ <b>${fmt(pa, 1)}</b> : il a ${pa > 100 ? "augmenté" : "diminué"}.`, t > 100 !== pa > 100 ? "Les deux indicateurs divergent : les prix relatifs ont évolué dans un sens, mais la variation du volume exporté joue en sens inverse et l’emporte." : "Les deux indicateurs vont dans le même sens, la variation du volume exporté ne fait ici qu’amplifier ou atténuer l’effet des prix.", "Un pays qui exporte surtout une matière première subit des termes de l’échange très variables. C’est un des arguments de Prebisch et de Singer en faveur de la diversification, mais la thèse d’une dégradation tendancielle reste discutée."); } },

  { id: "co3-smoot", theme: "commerce", niveau: 3, type: "qcm", notion: "avantage-comparatif",
    titre: "La guerre commerciale des années 1930, lue comme un jeu", competence: "Appliquer la théorie des jeux à une escalade de droits de douane et en tirer le sens d’un accord commercial.",
    enonce: P("En 1930, les États-Unis relèvent fortement leurs droits de douane avec le tarif Smoot-Hawley, et de nombreux partenaires répliquent. Pour modéliser cette escalade, supposons deux pays, A et B, qui choisissent chacun, sans se concerter et une seule fois, entre le libre-échange et un droit de douane. Les gains (A, B) sont donnés en unités de bien-être, données d’exemple.") +
      `<table><thead><tr><th></th><th>B : libre-échange</th><th>B : droit de douane</th></tr></thead><tbody><tr><td>A : libre-échange</td><td>(3 ; 3)</td><td>(1 ; 4)</td></tr><tr><td>A : droit de douane</td><td>(4 ; 1)</td><td>(2 ; 2)</td></tr></tbody></table>` +
      P("Quelle conclusion tirer de ce jeu ?"),
    options: ["Chaque pays a intérêt à taxer, quoi que fasse l’autre : les deux taxent et obtiennent moins que s’ils avaient coopéré.", "Chaque pays choisit le libre-échange, qui rapporte le plus au total : ce résultat est donc celui du jeu.", "Seul le pays le plus grand taxe, l’autre choisit le libre-échange pour limiter ses pertes.", "Les deux pays taxent, et ce résultat est le meilleur que chacun puisse obtenir, ce qui rend un accord superflu."], c: 0, pourquoi: [null, "Le libre-échange est le meilleur résultat d’ensemble, mais il n’est pas stable : si B choisit le libre-échange, A gagne 4 en taxant au lieu de 3.", "La taille des pays ne figure pas dans le jeu. Chacun a la même stratégie dominante.", "Le résultat (2 ; 2) est moins bon pour les deux que (3 ; 3) : il n’est donc pas le meilleur possible, et un accord a justement une raison d’être."],
    explication: P("Quoi que fasse B, A gagne plus en taxant : 4 plutôt que 3 si B pratique le libre-échange, 2 plutôt que 1 si B taxe. Il en va de même pour B. Taxer est une <b>stratégie dominante</b> et l’équilibre est (2 ; 2), moins bon pour les deux que (3 ; 3). C’est un <b>dilemme du prisonnier</b>.", "L’épisode de 1930 en est l’illustration : chaque pays protège son marché, les représailles se multiplient et le commerce mondial recule fortement entre 1929 et 1933, avec la crise. Les économistes discutent de la part exacte des droits de douane dans cette chute.", "Après 1945, le GATT puis l’OMC cherchent à sortir de ce dilemme. Les pays s’engagent à baisser leurs droits de manière réciproque et un mécanisme de règlement des différends rend la promesse crédible, ce qui n’est possible que parce que le jeu est répété.") },

  { id: "co3-vf-regles", theme: "commerce", niveau: 3, type: "vf", notion: "institutions-inclusives",
    titre: "Les règles du commerce mondial", competence: "Appliquer les règles de l’OMC et la théorie des accords préférentiels à des cas.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Un pays membre de l’OMC abaisse à 2 % son droit de douane sur les chaussures venues d’un partenaire avec lequel il n’a aucun accord. Selon la clause de la nation la plus favorisée, il doit en principe appliquer aussi 2 % aux chaussures des autres membres.", true, "C’est le principe de base du système multilatéral : un avantage accordé à un membre est étendu aux autres. Les accords de libre-échange et les préférences pour les pays en développement font exception, mais ce n’est pas le cas ici."],
      ["Deux membres de l’OMC concluent un accord de libre-échange et ne se font plus payer de droits entre eux. Ce traitement de faveur viole en principe la clause de la nation la plus favorisée, car les autres membres n’en bénéficient pas.", false, "Les accords de libre-échange sont admis, à condition de couvrir l’essentiel des échanges entre les partenaires et de ne pas relever les droits envers les tiers. Ils sont une exception prévue à la clause."],
      ["Un accord de libre-échange peut réduire le bien-être d’un de ses membres, si celui-ci se met à acheter à un partenaire moins efficace un produit qu’il importait auparavant d’un pays tiers plus efficace.", true, "C’est le détournement de commerce décrit par Jacob Viner. Le produit du partenaire n’est devenu moins cher que grâce à l’exemption de droits : le pays renonce à un fournisseur moins coûteux et perd la recette douanière."],
      ["L’Organisation mondiale du commerce a été créée en 1947, au lendemain de la Seconde Guerre mondiale, pour faire baisser les droits de douane.", false, "C’est le <b>GATT</b>, l’Accord général sur les tarifs douaniers et le commerce, qui date de 1947. L’OMC lui a succédé en 1995 ; son siège est à Genève."]
    ] },

  { id: "co3-clusters", theme: "commerce", niveau: 3, type: "qcm", notion: "rendements-croissants",
    titre: "Pourquoi la pharmacie est-elle à Bâle ?", competence: "Appliquer la nouvelle économie géographique.",
    enonce: P("Une grande partie de l’industrie pharmaceutique suisse est concentrée autour de Bâle, et l’horlogerie dans l’Arc jurassien. Comment la nouvelle économie géographique de Krugman explique-t-elle ces concentrations ?"),
    options: ["Par des ressources naturelles propres à ces régions, comme l’eau du Rhin ou le bois du Jura.","Par une causalité cumulative, une avance initiale attirant entreprises et main-d’œuvre qualifiée.","Par l’avantage comparatif, ces régions offrant des salaires plus bas que le reste de la Suisse.","Par une décision de la Confédération, qui a réparti les grandes industries entre les cantons."], c: 1, pourquoi: ["Ni Bâle ni l’Arc jurassien ne disposent de ressources naturelles particulières pour la pharmacie ou l’horlogerie.", null, "La nouvelle économie géographique n’explique pas la concentration par des salaires plus bas, mais par l’avantage d’être proche des fournisseurs, des clients et de la main-d’œuvre spécialisée.", "Aucune autorité n’a réparti ces industries. Leur localisation résulte de l’histoire et des choix des entreprises."],
    explication: P("Selon Krugman, les <b>rendements croissants</b> et les coûts de transport favorisent la concentration : les entreprises s’installent là où se trouvent déjà les clients, les fournisseurs et la main-d’œuvre spécialisée, ce qui attire d’autres entreprises. Une petite avance historique se renforce d’elle-même.", "À Bâle, l’industrie chimique est née au XIXe siècle des teintures pour l’industrie textile, puis s’est tournée vers la pharmacie ; dans l’Arc jurassien, l’horlogerie s’est développée dès le XVIIIe siècle. L’histoire décide du lieu, la causalité cumulative fait le reste.") },

  { id: "co3-droits-us", theme: "commerce", niveau: 3, type: "redaction", notion: "surplus",
    titre: "Les droits de douane américains depuis 2025", competence: "Analyser une politique commerciale récente.",
    enonce: P("En août 2025, les États-Unis imposent des droits de douane additionnels de 39 % sur de nombreux produits suisses, l’un des taux les plus élevés appliqués à un pays développé. Une déclaration d’intention de novembre 2025 les ramène à 15 %. Le 20 février 2026, la Cour suprême des États-Unis juge que la loi invoquée n’autorisait pas ces droits. L’administration les remplace par une surtaxe temporaire de 10 %, puis, depuis le 24 juillet 2026, par de nouveaux droits additionnels fondés sur une autre loi. Certains secteurs, comme les produits pharmaceutiques, relèvent de règles distinctes. Fin 2026, les négociations se poursuivent et aucun accord définitif n’est signé.", "<b>Consigne :</b> qui paie ces droits de douane, et quelles sont leurs conséquences pour l’économie suisse ? Utilisez au moins une notion d’économie (incidence, élasticité, prix, avantage comparatif, taux de change), précisez quelles branches et régions sont les plus touchées, tenez compte de l’effet de l’instabilité des règles sur l’investissement, proposez au moins deux réponses possibles de la Suisse, puis concluez. Rattachez chaque position à une école ou à un auteur (libre-échange de Ricardo, droit de douane optimal d’un grand pays, protection des industries naissantes de List et de Chang, études empiriques sur les droits de 2018 et 2019) et dites sur quelle hypothèse ils s’opposent. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "La réponse explique que le droit de douane est payé à l’importation aux États-Unis, et que sa charge réelle se partage entre consommateurs américains et exportateurs suisses selon les élasticités (incidence).","Elle identifie les branches et régions suisses les plus touchées : horlogerie, machines, instruments, sous-traitants, Arc jurassien…", "Elle mobilise au moins une notion : élasticité, incidence fiscale, prix, avantage comparatif, taux de change…", "Elle propose au moins deux réponses possibles : négociation, diversification des marchés, investissements aux États-Unis, chômage partiel, innovation, accords avec d’autres partenaires…", "Elle tient compte de l’instabilité des règles (changements de taux et de base légale) et de son effet sur l’investissement.", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Les écoles en présence.</b> Dans la tradition de Ricardo, un droit de douane est une perte pour le pays qui l’impose, car il détourne vers des producteurs moins efficaces. La théorie du droit de douane optimal nuance : un pays assez grand pour peser sur le prix mondial peut reporter une partie du droit sur ses fournisseurs. Les deux s’opposent sur l’hypothèse du pouvoir de marché, c’est-à-dire sur la réaction de l’offre étrangère, et sur l’absence de représailles. Les études empiriques de 2018 et 2019 (Amiti, Redding et Weinstein ; Fajgelbaum et ses coauteurs) ont conclu à une répercussion presque complète sur les prix américains : l’hypothèse du pouvoir de marché ne s’est pas vérifiée. List et Chang, enfin, défendent un droit temporaire pour construire un avantage comparatif, hypothèse que ne partage pas Ricardo, pour qui les avantages sont donnés. Ce raisonnement vise des industries naissantes et s’applique mal à une taxe générale.", "Le droit de douane est payé par l’importateur américain, mais sa charge réelle se partage. Si les clients américains peuvent facilement se tourner vers d’autres produits, la demande est <b>élastique</b> : les exportateurs suisses doivent baisser leurs prix pour rester compétitifs et supportent l’essentiel du coût. Pour des produits difficilement remplaçables, comme certaines montres de luxe, les consommateurs américains paient une plus grande part.", "Les conséquences touchent surtout les branches très exposées au marché américain, comme l’horlogerie, les machines et les instruments de précision, ainsi que leurs sous-traitants, souvent des PME de l’Arc jurassien. Elles peuvent réduire les exportations, les marges, les investissements et l’emploi, surtout si le franc reste fort.", "La Suisse peut négocier, comme elle l’a fait en novembre 2025 pour obtenir le passage de 39 % à 15 %, diversifier ses débouchés grâce à ses accords de libre-échange, soutenir les entreprises par le chômage partiel, et miser sur l’innovation et la qualité. Les entreprises peuvent aussi produire davantage aux États-Unis. Ces droits de douane rappellent qu’une petite économie ouverte dépend de règles commerciales qu’elle ne fixe pas seule.", "L’épisode montre aussi le coût de l’incertitude. Quand le taux change plusieurs fois en un an, les entreprises reportent leurs investissements, même si le taux final est modéré. Les études menées sur les droits de douane américains de 2018 et 2019 ont par ailleurs mesuré une répercussion presque complète sur les prix payés aux États-Unis, ce qui nuance l’idée que l’exportateur supporte l’essentiel de la charge.") },

  { id: "co3-dependance", theme: "commerce", niveau: 3, type: "document", notion: "institutions-inclusives",
    titre: "La dépendance à une matière première", competence: "Mesurer la vulnérabilité d’une structure d’exportations à partir de données de la Banque mondiale.",
    enonce: P("Le tableau compare trois pays dont les exportations n’ont pas la même composition. Entre 2013 et 2016, le cours mondial du cuivre a fortement baissé, puis il est nettement remonté jusqu’en 2021.") +
      `<table><thead><tr><th></th><th>Zambie</th><th>Chili</th><th>Mexique</th></tr></thead><tbody><tr><td>Minerais et métaux, en % des exportations de marchandises (2024)</td><td>73,0</td><td>55,7</td><td>2,1</td></tr><tr><td>Produits manufacturés, en % des exportations de marchandises (2024)</td><td>14,1</td><td>12,6</td><td>79,0</td></tr><tr><td>Exportations de marchandises en 2013 (milliards de dollars)</td><td>10,6</td><td>76,8</td><td>380,0</td></tr><tr><td>Exportations de marchandises en 2016 (milliards de dollars)</td><td>6,4</td><td>60,7</td><td>374,0</td></tr><tr><td>Exportations de marchandises en 2021 (milliards de dollars)</td><td>11,0</td><td>94,6</td><td>495,0</td></tr></tbody></table><p class="ex-source">Source : Banque mondiale, Indicateurs du développement dans le monde, séries TX.VAL.MMTL.ZS.UN, TX.VAL.MANF.ZS.UN et TX.VAL.MRCH.CD.WT, mise à jour du 11 novembre 2026. Dollars courants.</p>` +
      P("Calculez, pour chaque pays, la variation de ses exportations entre 2013 et 2016, puis entre 2016 et 2021. Quelle analyse est la plus juste ?"),
    options: ["La Zambie voit ses recettes d’exportation chuter de 40 % puis bondir de plus de 70 %. Elle subit les cours du cuivre, ce qu’une diversification limiterait.", "Le Chili est exposé autant que la Zambie, puisque les minerais et métaux dominent aussi ses exportations et que son économie dépend du cuivre.", "Le Mexique a des exportations stables sur toute la période, car les prix des produits manufacturés ne varient pas d’une année à l’autre.", "La reprise de la Zambie après 2016 montre que dépendre du cuivre est un avantage, puisque ses exportations ont presque doublé en cinq ans."], c: 0,
    pourquoi: [null, "Les exportations du Chili ont baissé de 21 % entre 2013 et 2016, deux fois moins que celles de la Zambie (−40 %). Les minerais y pèsent moins lourd (56 % contre 73 %) et le reste des exportations amortit le choc.", "Les exportations du Mexique ont augmenté de 32 % entre 2016 et 2021. Elles varient avec la demande mondiale, mais elles n’ont presque pas baissé quand le cuivre s’est effondré (−1,6 % de 2013 à 2016).", "La hausse après 2016 ne fait que compenser la chute. De 2013 à 2021, les exportations de la Zambie n’augmentent que de 4 %, contre 23 % pour le Chili et 30 % pour le Mexique."],
    explication: P("Variations de 2013 à 2016 : Zambie 6,4 ÷ 10,6 − 1 ≈ <b>−40 %</b>, Chili ≈ <b>−21 %</b>, Mexique ≈ <b>−1,6 %</b>. Variations de 2016 à 2021 : Zambie ≈ <b>+72 %</b>, Chili ≈ <b>+56 %</b>, Mexique ≈ <b>+32 %</b>. Plus la part des minerais est forte, plus les recettes d’exportation suivent les cours.", "Quand les recettes chutent de 40 %, les recettes fiscales, les réserves de devises et la monnaie suivent. La Zambie, très endettée, a fait défaut sur sa dette extérieure en 2020. Diversifier les exportations réduit cette exposition, mais demande des années d’investissement.", "Les économistes parlent parfois de « malédiction des ressources ». Une forte dépendance aux matières premières peut s’accompagner d’une croissance instable et, selon Acemoglu et Robinson, d’institutions extractives quand une élite contrôle la rente. Le Chili montre qu’elle n’est pas une fatalité, grâce à un fonds de stabilisation qui épargne une partie des recettes du cuivre quand les cours sont hauts.", "Dès 1950, Raúl Prebisch et Hans Singer soutenaient que les prix des matières premières tendent à baisser par rapport à ceux des produits manufacturés, ce qui dégrade les termes de l’échange des pays qui en dépendent. Cette thèse a inspiré les politiques d’industrialisation en Amérique latine et reste débattue.") },
  { id: "co1-fait-valeur", theme: "commerce", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Constat ou jugement de valeur caché ?", competence: "Repérer le jugement de valeur qui se cache derrière une phrase d’apparence factuelle, et reconnaître qu’une prévision se vérifie.",
    enonce: P("Un jugement de valeur peut se cacher dans une phrase sans « devrait » ni « injuste ». Pour chaque phrase, dites s’il s’agit d’un <b>constat</b>, que l’on peut vérifier avec des données, même s’il se révèle faux, ou d’un <b>jugement de valeur</b>. Une prévision se vérifiera avec le temps : elle compte comme un constat."),
    affirmations: [
      ["Un droit de douane de 20 % sur l’acier fera monter le prix de l’acier dans le pays qui l’impose.", true, "C’est une prévision, et on pourra la vérifier en comparant les prix avant et après le droit. Elle peut se révéler fausse, ce qui n’en fait pas un jugement."],
      ["Avec un excédent commercial de 6 % du PIB, ce pays a une économie en bonne santé.", false, "Le chiffre de l’excédent se vérifie, mais « en bonne santé » est un jugement : il suppose qu’un excédent est un bien. Un excédent peut aussi refléter une demande intérieure faible."],
      ["Si la monnaie d’un pays se déprécie, ses importations coûteront plus cher en monnaie nationale.", true, "C’est une prévision vérifiable : on peut mesurer les prix des importations avant et après la dépréciation."],
      ["L’ouverture des frontières a sacrifié les ouvriers du textile des régions industrielles.", false, "Les fermetures d’usines et les emplois perdus se mesurent, mais « sacrifié » est un jugement : il dit que ces pertes étaient un prix à ne pas payer. On peut éclairer le débat avec des faits, pas le trancher."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "co1-conversion", theme: "commerce", niveau: 1, type: "calcul", notion: "taux-de-change",
    titre: "Payer une machine en euros", competence: "Convertir un prix d’une monnaie dans une autre.",
    gen: () => ({ prix: rnd(8, 40) * 500, e: pick([0.92, 0.94, 0.96, 0.98]) }),
    enonce: (p) => P(`Une entreprise suisse achète en Allemagne une machine facturée <b>${fmt(p.prix)} euros</b>. Le jour du paiement, un euro vaut <b>${fmt(p.e)} franc</b>.`, "Combien de francs doit-elle débourser ?"),
    champs: [{ label: "Prix en francs", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [Math.round(p.prix * p.e * 100) / 100],
    indice: "Chaque euro coûte un peu moins d’un franc. Le montant en francs est donc un peu plus petit que le montant en euros.",
    correction: (p) => P(`Prix en francs = ${fmt(p.prix)} × ${fmt(p.e)}`, `= <b>${fmt(p.prix * p.e)} francs</b>.`, "Si le franc s’apprécie encore avant le paiement, la machine coûtera moins de francs. C’est l’avantage d’une monnaie forte pour ceux qui importent, et un risque pour ceux qui vendent à l’étranger.") },

  { id: "co1-graph-solde", theme: "commerce", niveau: 1, type: "graphique",
    titre: "Lire un solde commercial", competence: "Interpréter un solde commercial positif ou négatif sur un graphique.",
    enonce: P("Le graphique donne le solde commercial d’un pays, c’est-à-dire ses exportations moins ses importations de biens, en milliards.", "Que montre-t-il pour 2022 ?"),
    fig: () => X.barres({ cats: ["2020", "2021", "2022", "2023", "2024"], vals: [12, 5, -8, -3, 6], ymin: -11, ymax: 15, dec: 0, col: "d", aria: "Solde commercial de 2020 à 2024 : 12, 5, moins 8, moins 3 puis 6 milliards", caption: "Solde commercial en milliards. Données inventées pour l’exercice." }),
    options: ["Le pays a importé pour 8 milliards de plus qu’il n’a exporté.", "Le pays a exporté pour 8 milliards de plus qu’il n’a importé.", "Les exportations du pays ont diminué de 8 milliards en un an.", "Le pays a exporté pour 8 milliards de biens seulement."], c: 0,
    pourquoi: [null, "Ce serait un solde de +8 milliards, avec une barre au-dessus de l’axe. La barre de 2022 est en dessous. Le solde est négatif.", "Le graphique ne donne pas les exportations, mais leur écart avec les importations. Le solde a reculé de 13 milliards, et cela peut venir d’une hausse des importations autant que d’une baisse des exportations.", "Le solde ne dit rien du montant des exportations. Un pays peut exporter 300 milliards et avoir un solde de −8 milliards s’il en importe 308."],
    explication: P("Solde commercial = exportations − importations. Un solde de <b>−8 milliards</b> est un <b>déficit</b>. Le pays a acheté à l’étranger pour 8 milliards de plus qu’il n’y a vendu.", "Un déficit n’est pas en soi un signe de faiblesse. Il peut refléter une demande intérieure forte ou des achats de machines. Il doit en revanche être financé, par des revenus venus de l’étranger ou par des emprunts.") },

  { id: "co1-instruments", theme: "commerce", niveau: 1, type: "qcm",
    titre: "Reconnaître un instrument de protection", competence: "Distinguer les principaux instruments de la politique commerciale.",
    enonce: P("Pour protéger ses constructeurs, un pays décide que 10 000 voitures étrangères au plus pourront entrer sur son territoire chaque année.", "De quel instrument s’agit-il ?"),
    options: ["Un contingent, c’est-à-dire une quantité maximale d’importations.", "Un droit de douane, c’est-à-dire une taxe sur chaque voiture importée.", "Une subvention, c’est-à-dire une aide versée aux constructeurs du pays.", "Une norme technique, c’est-à-dire une exigence imposée aux produits vendus."], c: 0,
    pourquoi: [null, "Un droit de douane renchérit chaque voiture importée sans fixer de plafond. Ici le pays ne taxe pas, il limite le nombre.", "Une subvention aide les producteurs du pays sans limiter les importations. Ici la mesure porte directement sur les voitures étrangères.", "Une norme fixe ce que le produit doit respecter, par exemple un niveau d’émissions. Elle ne plafonne pas le nombre de voitures."],
    explication: P("Limiter la <b>quantité</b> importée, c’est fixer un <b>contingent</b>, aussi appelé quota. Comme un droit de douane, il raréfie le produit et fait monter son prix dans le pays.", "La différence est dans le partage du gain. Avec un droit de douane, l’État encaisse une recette. Avec un contingent, ce sont les importateurs qui disposent d’une licence, ou les exportateurs étrangers, qui profitent du prix plus élevé.") },

  /* ----- Niveau 2 ----- */
  { id: "co2-graph-tarif", theme: "commerce", niveau: 2, type: "graphique", notion: "surplus",
    titre: "Les effets d’un droit de douane", competence: "Repérer sur un graphique la recette douanière et la perte sèche d’un droit de douane.",
    enonce: P("Un petit pays importe un bien au prix mondial de 40 francs. Il instaure un droit de douane de 10 francs par unité, et le prix intérieur passe à 50 francs. Quatre surfaces sont repérées, a, b, c et d.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 88, ymax: 108, ylab: "Prix (fr.)", xlab: "Quantité", aria: "Droit de douane dans un petit pays : offre et demande intérieures, prix mondial et prix avec droit",
      zones: [{ pts: [[0, 40], [20, 40], [30, 50], [0, 50]], col: "o", lab: "a", at: [11, 45] }, { pts: [[20, 40], [30, 40], [30, 50]], col: "r", lab: "b", at: [27, 43.5] }, { pts: [[30, 40], [50, 40], [50, 50], [30, 50]], col: "p", lab: "c", at: [40, 45] }, { pts: [[50, 40], [60, 40], [50, 50]], col: "r", lab: "d", at: [53, 43.5] }],
      gx: [[20, "20"], [30, "30"], [50, "50"], [60, "60"]], gy: [[40, "40"], [50, "50"]],
      lignes: [{ pts: [[0, 100], [80, 20]], col: "d", lab: "D", at: [80, 20], dx: 6, dy: 4 }, { pts: [[0, 20], [72, 92]], col: "o", lab: "O", at: [72, 92], dx: 6, dy: 4 }, { pts: [[0, 40], [80, 40]], col: "n", dash: true }, { pts: [[0, 50], [80, 50]], col: "n" }],
      caption: "D est la demande intérieure, O l’offre des producteurs du pays. Le trait pointillé marque le prix mondial (40 francs), le trait plein le prix avec le droit de douane (50 francs)." }),
    options: ["La recette douanière est la surface c, soit 200 francs, et la perte sèche la somme de b et de d, soit 100 francs.", "La recette douanière est la surface a, soit 250 francs, et le droit de douane ne crée pas de perte sèche.", "La recette douanière est la surface c, soit 200 francs, et elle compense exactement la perte des consommateurs.", "Les consommateurs perdent les surfaces b et d, soit 100 francs, et les producteurs gagnent a et c."], c: 0,
    pourquoi: [null, "La surface a est le gain des producteurs du pays, qui vendent plus et plus cher. La recette de l’État porte sur les 20 unités encore importées, soit la surface c.", "Les consommateurs perdent a + b + c + d, soit 550 francs. La recette de 200 francs et le gain des producteurs de 250 francs ne compensent pas tout. Il manque b et d.", "Les consommateurs perdent les quatre surfaces. Les producteurs ne gagnent que a. La surface c revient à l’État."],
    explication: P("Au prix de 50 francs, les producteurs du pays offrent 30 unités au lieu de 20 et les consommateurs en achètent 50 au lieu de 60. Les importations tombent de 40 à <b>20 unités</b>.", "Recette douanière : c = 10 × 20 = <b>200 francs</b>. Gain des producteurs : a = ½ × (20 + 30) × 10 = 250 francs. Perte des consommateurs : a + b + c + d = ½ × (60 + 50) × 10 = 550 francs.", "La différence, b + d = 50 + 50 = <b>100 francs</b>, n’est gagnée par personne. Le triangle b correspond à une production plus coûteuse que les importations, le triangle d à une consommation à laquelle on renonce.", "Ce résultat vaut pour un petit pays, qui ne peut pas influencer le prix mondial. Un grand pays peut faire baisser ce prix et reporter une partie du droit sur ses fournisseurs.") },

  { id: "co2-change-reel", theme: "commerce", niveau: 2, type: "calcul", notion: "taux-de-change",
    titre: "Le taux de change réel", competence: "Calculer la variation d’un taux de change réel à partir du change nominal et des inflations.",
    gen: () => ({ app: pick([2, 4, 5, 8]), pi: pick([0, 0.5, 1]), pis: pick([2, 3, 5, 6]) }),
    enonce: (p) => P(`En un an, la monnaie d’un pays s’apprécie de <b>${p.app} %</b> face à celles de ses partenaires. Ses prix augmentent de <b>${fmt(p.pi)} %</b>, ceux de ses partenaires de <b>${p.pis} %</b>.`, "De combien ses produits ont-ils renchéri par rapport aux produits étrangers ? Donnez la variation du taux de change réel par le calcul approché (une décimale), puis par le calcul exact (deux décimales). Indiquez un signe moins pour une baisse."),
    champs: [{ label: "Calcul approché", unite: "%", tol: 0.01 }, { label: "Calcul exact", unite: "%", tol: 0.02 }],
    reponses: (p) => [Math.round((p.app + p.pi - p.pis) * 10) / 10, Math.round(((1 + p.app / 100) * (1 + p.pi / 100) / (1 + p.pis / 100) - 1) * 10000) / 100],
    indice: "Le taux de change réel compare les prix des deux pays exprimés dans la même monnaie. L’appréciation et l’inflation du pays renchérissent ses produits, l’inflation étrangère joue en sens inverse.",
    correction: (p) => { const a = p.app + p.pi - p.pis, x = ((1 + p.app / 100) * (1 + p.pi / 100) / (1 + p.pis / 100) - 1) * 100; return P('Le taux de change réel varie comme l’appréciation de la monnaie, plus l’inflation du pays, moins l’inflation des partenaires.', `Calcul approché : ${p.app} + ${fmt(p.pi)} − ${p.pis} = <b>${fmt(a, 1)} %</b>.`, `Calcul exact : ${fmt(1 + p.app / 100, 3)} × ${fmt(1 + p.pi / 100, 3)} ÷ ${fmt(1 + p.pis / 100, 3)} − 1 ≈ <b>${fmt(x, 2)} %</b>.`, a > 0 ? "Le taux de change réel s’apprécie. Les produits du pays deviennent plus chers face aux produits étrangers, et ses exportateurs perdent en compétitivité." : a < 0 ? "Le taux de change réel se déprécie, malgré l’appréciation nominale. L’inflation plus forte à l’étranger fait plus que compenser la hausse de la monnaie, et les exportateurs du pays gagnent en compétitivité." : "Le taux de change réel est à peu près stable. L’appréciation de la monnaie compense tout juste l’écart d’inflation, comme le prévoit la parité de pouvoir d’achat.", "C’est pourquoi une monnaie qui s’apprécie n’est pas toujours un handicap. Quand un pays a moins d’inflation que ses partenaires, l’appréciation nominale ne fait souvent que rétablir l’équilibre des prix."); } },

  { id: "co2-doc-balance", theme: "commerce", niveau: 2, type: "document",
    titre: "Lire une balance des paiements", competence: "Calculer un solde courant et en tirer la position financière d’un pays.",
    enonce: P("Voici la balance des transactions courantes d’un pays pour une année, en milliards.") +
      `<table><thead><tr><th>Poste</th><th>Solde</th></tr></thead><tbody><tr><td>Biens (exportations moins importations)</td><td>+20</td></tr><tr><td>Services (tourisme, transports, licences)</td><td>+15</td></tr><tr><td>Revenus (salaires, intérêts et dividendes reçus moins versés)</td><td>+25</td></tr><tr><td>Transferts courants (aide, envois de fonds des migrants)</td><td>−10</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Le solde courant vaut +50 milliards, et le pays place ce montant à l’étranger.", "Le solde courant vaut +20 milliards, soit l’excédent des échanges de biens.", "Le solde courant vaut +50 milliards, et le pays emprunte ce montant à l’étranger.", "Le solde courant vaut +70 milliards, soit la somme des quatre postes."], c: 0,
    pourquoi: [null, "L’excédent des biens n’est que le solde commercial. Le solde courant ajoute les services, les revenus et les transferts.", "Le total est juste, mais le sens est inversé. Un pays qui reçoit plus qu’il ne dépense dégage une épargne, qu’il prête ou investit à l’étranger.", "Les transferts ont un solde négatif et se soustraient. La somme est 20 + 15 + 25 − 10 = 50, et non 70."],
    explication: P("Solde courant = 20 + 15 + 25 − 10 = <b>+50 milliards</b>.", "Un pays en excédent courant gagne à l’étranger plus qu’il n’y dépense. La différence s’accumule sous forme de créances sur le reste du monde, par des prêts, des achats de titres ou des investissements d’entreprises. À l’inverse, un pays en déficit courant s’endette ou vend des actifs.", "Le solde courant est aussi égal à l’épargne du pays moins son investissement. Un excédent durable signale donc une épargne abondante, pas seulement des exportateurs performants. C’est le cas de la Suisse, dont l’excédent tient beaucoup aux revenus de ses placements à l’étranger.") },

  { id: "co2-marge-export", theme: "commerce", niveau: 2, type: "calcul", notion: "taux-de-change",
    titre: "La marge d’un exportateur et le franc fort", competence: "Mesurer l’effet d’une variation de change sur la marge d’une entreprise exportatrice.",
    gen: () => { const prix = pick([800, 1000, 1200, 1500]), e0 = pick([1.05, 1.1]); return { prix, e0, e1: pick([0.93, 0.95, 0.97]), cout: Math.round(prix * e0 * 0.82 / 10) * 10 }; },
    enonce: (p) => P(`Une entreprise suisse vend en Allemagne un instrument de mesure <b>${fmt(p.prix)} euros</b> pièce. Chaque pièce lui coûte <b>${fmt(p.cout)} francs</b> à produire, entièrement en Suisse. L’euro passe de <b>${fmt(p.e0)} franc</b> à <b>${fmt(p.e1)} franc</b>, et l’entreprise maintient son prix en euros pour garder ses clients.`, "Calculez sa marge par pièce avant et après la baisse de l’euro, puis la variation de cette marge en % (une décimale, signe moins pour une baisse)."),
    champs: [{ label: "Marge avant", unite: "fr.", tol: 0.5 }, { label: "Marge après", unite: "fr.", tol: 0.5 }, { label: "Variation de la marge", unite: "%", tol: 0.1 }],
    reponses: (p) => { const m0 = p.prix * p.e0 - p.cout, m1 = p.prix * p.e1 - p.cout; return [Math.round(m0 * 100) / 100, Math.round(m1 * 100) / 100, Math.round((m1 / m0 - 1) * 1000) / 10]; },
    indice: "Convertissez d’abord la recette en francs aux deux cours. Le coût, lui, ne change pas.",
    correction: (p) => { const r0 = p.prix * p.e0, r1 = p.prix * p.e1, m0 = r0 - p.cout, m1 = r1 - p.cout; return P(`Recette par pièce : ${fmt(p.prix)} × ${fmt(p.e0)} = ${fmt(r0)} francs avant, ${fmt(p.prix)} × ${fmt(p.e1)} = ${fmt(r1)} francs après.`, `Marge avant = ${fmt(r0)} − ${fmt(p.cout)} = <b>${fmt(m0)} francs</b>. Marge après = ${fmt(r1)} − ${fmt(p.cout)} = <b>${fmt(m1)} francs</b>.`, `Variation = (${fmt(m1)} − ${fmt(m0)}) ÷ ${fmt(m0)} × 100 ≈ <b>${fmt((m1 / m0 - 1) * 100, 1)} %</b>.`, `La recette ne baisse que de ${fmt((1 - p.e1 / p.e0) * 100, 1)} %, mais la marge fond bien davantage, parce que les coûts restent en francs. Un exportateur réduit ce risque en achetant une partie de ses fournitures en euros, en se couvrant sur le marché des changes ou en vendant des produits assez spécialisés pour pouvoir relever son prix.`); } },

  /* ----- Niveau 3 ----- */
  { id: "co3-couverture", theme: "commerce", niveau: 3, type: "calcul", notion: "taux-de-change",
    titre: "Se couvrir contre le risque de change", competence: "Calculer un cours à terme par la parité couverte des taux d’intérêt et évaluer une couverture.",
    gen: () => { const S = pick([0.92, 0.94, 0.96]); return { m: pick([200, 500, 800]) * 1000, S, ie: pick([2, 3, 4]), ic: pick([0, 0.5, 1]), S1: Math.round((S - pick([0.03, 0.05])) * 100) / 100 }; },
    enonce: (p) => P(`Un exportateur suisse recevra <b>${fmt(p.m)} euros</b> dans six mois. Aujourd’hui, un euro vaut <b>${fmt(p.S)} franc</b>. Pour un placement à six mois, les taux annuels sont de <b>${fmt(p.ic)} %</b> en francs et de <b>${p.ie} %</b> en euros.`, `Calculez le cours à terme de l’euro à six mois selon la parité couverte des taux d’intérêt (quatre décimales), la recette en francs que garantit une vente à terme, puis la recette sans couverture si l’euro tombe à <b>${fmt(p.S1)} franc</b>.`),
    champs: [{ label: "Cours à terme", unite: "fr. pour 1 €", tol: 0.0002 }, { label: "Recette avec couverture", unite: "fr.", tol: 100 }, { label: "Recette sans couverture", unite: "fr.", tol: 0.5 }],
    reponses: (p) => { const F = p.S * (1 + p.ic / 200) / (1 + p.ie / 200); return [Math.round(F * 10000) / 10000, Math.round(p.m * F), Math.round(p.m * p.S1)]; },
    indice: "Placer des francs pendant six mois doit rapporter autant que les changer en euros, placer ces euros et les revendre à terme. Sur six mois, un taux annuel compte pour moitié.",
    correction: (p) => { const F = p.S * (1 + p.ic / 200) / (1 + p.ie / 200); return P(`Parité couverte : F = S × (1 + taux en francs sur six mois) ÷ (1 + taux en euros sur six mois).`, `F = ${fmt(p.S)} × ${fmt(1 + p.ic / 200, 4)} ÷ ${fmt(1 + p.ie / 200, 4)} ≈ <b>${fmt(F, 4)} franc</b> pour un euro.`, `Recette avec couverture : ${fmt(p.m)} × ${fmt(F, 4)} ≈ <b>${fmt(p.m * F, 0)} francs</b>, connue dès aujourd’hui.`, `Recette sans couverture, si l’euro vaut ${fmt(p.S1)} franc : ${fmt(p.m)} × ${fmt(p.S1)} = <b>${fmt(p.m * p.S1)} francs</b>.`, "Le cours à terme est inférieur au cours du jour, parce que les taux sont plus bas en francs qu’en euros. Cet écart est le coût de la couverture. Elle ne fait pas gagner d’argent en moyenne, elle remplace une recette incertaine par une recette connue.", "Si l’écart de taux ne correspondait pas à l’écart entre cours à terme et cours du jour, on pourrait emprunter dans une monnaie et prêter dans l’autre sans risque. L’arbitrage fait disparaître ce gain, ce qui fonde la parité couverte. La parité non couverte, qui prédit que la monnaie à taux élevé se déprécie en moyenne, est beaucoup moins bien vérifiée."); } },

  { id: "co3-krugman", theme: "commerce", niveau: 3, type: "calcul", notion: "rendements-croissants",
    titre: "Taille du marché et variété des produits", competence: "Résoudre un modèle de concurrence monopolistique et étudier l’effet de l’ouverture.",
    gen: () => { const n = pick([4, 5, 10]), F = pick([200, 500]); return { n, F, c: pick([20, 30, 40]), S: 0.02 * F * n * n }; },
    enonce: (p) => P(`Dans une branche, chaque entreprise fabrique une variété différente du même produit. Avec n entreprises, chacune vend S ÷ n unités, où S = <b>${fmt(p.S)}</b> est la taille du marché. Son coût moyen est <b>CM = ${p.c} + ${p.F} × n ÷ S</b>, car elle supporte un coût fixe de ${p.F}. La concurrence entre variétés fixe le prix à <b>P = ${p.c} + 50 ÷ n</b>.`, "L’entrée de nouvelles entreprises se poursuit jusqu’à ce que le profit soit nul, c’est-à-dire P = CM. Calculez le nombre d’entreprises et le prix à l’équilibre. Le pays s’ouvre ensuite à des partenaires, et la taille du marché est multipliée par quatre. Calculez le nouveau nombre d’entreprises et le nouveau prix."),
    champs: [{ label: "Nombre d’entreprises", unite: "", tol: 0.05 }, { label: "Prix", unite: "fr.", tol: 0.01 }, { label: "Nombre après l’ouverture", unite: "", tol: 0.05 }, { label: "Prix après l’ouverture", unite: "fr.", tol: 0.01 }],
    reponses: (p) => [p.n, p.c + 50 / p.n, 2 * p.n, p.c + 25 / p.n],
    indice: "Écrivez P = CM. Le coût marginal disparaît des deux côtés, et il reste une équation en n².",
    correction: (p) => P(`Profit nul : ${p.c} + 50 ÷ n = ${p.c} + ${p.F} × n ÷ ${fmt(p.S)}, donc n² = 50 × ${fmt(p.S)} ÷ ${p.F} = ${p.n * p.n}.`, `Il y a <b>${p.n} entreprises</b>, et le prix vaut ${p.c} + 50 ÷ ${p.n} = <b>${fmt(p.c + 50 / p.n)} francs</b>.`, `Avec un marché de ${fmt(4 * p.S)}, n² = 50 × ${fmt(4 * p.S)} ÷ ${p.F} = ${4 * p.n * p.n}. Il y a <b>${2 * p.n} entreprises</b> et le prix tombe à ${p.c} + 50 ÷ ${2 * p.n} = <b>${fmt(p.c + 25 / p.n)} francs</b>.`, `Le marché a quadruplé, le nombre d’entreprises a seulement doublé. Chacune produit deux fois plus qu’avant et amortit mieux son coût fixe. Les consommateurs gagnent deux fois, par un prix plus bas et par un choix plus large.`, "C’est le modèle de Paul Krugman (1979). Il explique pourquoi des pays semblables échangent des produits semblables, des voitures contre des voitures, ce que le modèle de Ricardo et celui de Heckscher et Ohlin expliquent mal. Les gains viennent des rendements croissants et de la variété, non de différences entre pays. Le modèle laisse de côté le sort des entreprises qui disparaissent lors de l’ouverture, question que Marc Melitz a reprise en distinguant les entreprises selon leur productivité.") },

  { id: "co3-graph-echange", theme: "commerce", niveau: 3, type: "graphique", notion: "avantage-comparatif",
    titre: "Consommer au-delà de ce qu’on peut produire", competence: "Lire les gains de l’échange sur une frontière des possibilités de production.",
    enonce: P("Un pays peut produire au plus 100 unités de drap ou 50 unités de vin, ou toute combinaison située sur sa frontière de production. Sur le marché mondial, une unité de vin s’échange contre une unité de drap. Le pays consomme au point C.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 112, ymax: 112, ylab: "Vin", xlab: "Drap", aria: "Frontière de production d’un pays et droite d’échange au prix mondial",
      gx: [[60, "60"], [100, "100"]], gy: [[20, "20"], [40, "40"], [50, "50"], [100, "100"]], reperes: [[60, 40]],
      lignes: [{ pts: [[0, 50], [100, 0]], col: "d", lab: "frontière de production", at: [3, 20] }, { pts: [[0, 100], [100, 0]], col: "o", dash: true, lab: "droite d’échange", at: [22, 78], dx: 10, dy: 0 }],
      points: [{ x: 100, y: 0, lab: "S", dx: -4, dy: -12, anc: "end" }, { x: 60, y: 40, lab: "C", col: "o", dx: 10, dy: -6 }, { x: 60, y: 20, col: "d" }],
      caption: "S est le point de production du pays quand il échange, C son point de consommation." }),
    options: ["Le pays produit 100 de drap, en exporte 40 contre 40 de vin, et consomme plus qu’il ne pourrait produire seul.", "Le pays produit 60 de drap et 40 de vin, car le commerce augmente sa capacité de production.", "Le pays se spécialise dans le vin, puisque c’est le bien qui s’échange le moins cher à l’étranger.", "Le pays produit 100 de drap et consomme 100 de drap et 100 de vin, les deux extrémités de la droite d’échange."], c: 0,
    pourquoi: [null, "Le point C est au-delà de la frontière. Avec ses propres moyens, le pays qui produit 60 de drap n’obtient que 20 de vin. Le commerce ne change pas ce qu’il sait produire, il change ce qu’il peut consommer.", "Un bien bon marché à l’étranger est un bien qu’on a intérêt à importer. Produire une unité de vin coûte au pays deux unités de drap, alors qu’il peut l’acheter contre une seule.", "La droite d’échange se parcourt, elle ne s’additionne pas. Chaque unité de vin obtenue coûte une unité de drap. Avec 100 de drap, le pays peut avoir 60 de drap et 40 de vin, ou 0 de drap et 100 de vin."],
    explication: P("Sans échange, une unité de vin coûte au pays <b>deux</b> unités de drap, la pente de sa frontière. Sur le marché mondial, elle n’en coûte qu’<b>une</b>. Le pays a un avantage comparatif dans le drap.", "Il se spécialise au point S (100 de drap, 0 de vin), exporte 40 de drap et reçoit 40 de vin. Il consomme en C, soit <b>60 de drap et 40 de vin</b>. Seul, avec 60 de drap, il n’aurait eu que 20 de vin.", "C’est le résultat de Ricardo. Il porte sur le pays dans son ensemble et suppose que les vignerons deviennent tisserands sans coût. Friedrich List, puis Ha-Joon Chang, objectent qu’une spécialisation dictée par les prix du moment peut enfermer un pays dans des activités sans avenir, et défendent une protection temporaire des industries naissantes.") },

  { id: "co3-red-libre-echange", theme: "commerce", niveau: 3, type: "redaction", notion: "avantage-comparatif",
    titre: "Le libre-échange profite-t-il à tous ?", competence: "Comparer plusieurs théories du commerce international et leurs conclusions sur l’ouverture.",
    enonce: P("Depuis 2018, plusieurs grandes économies ont relevé leurs droits de douane, et les subventions à l’industrie se multiplient. Le consensus favorable au libre-échange, dominant dans les années 1990, est contesté.", "<b>Consigne :</b> comparez au moins trois analyses de l’ouverture commerciale en les rattachant à leurs auteurs (Ricardo ; Heckscher, Ohlin et Samuelson ; Krugman ; List ou Chang ; Prebisch et Singer ; Rodrik). Dites pour chacune qui gagne et qui perd à l’échange, sur quelle hypothèse elle repose et quelle politique elle inspire. Appuyez-vous sur au moins un fait, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois analyses et nomme leurs auteurs.", "Elle dit pour chacune qui gagne et qui perd à l’échange (pays dans son ensemble, facteur abondant ou rare, consommateurs, pays exportateurs de matières premières).", "Elle identifie au moins une hypothèse qui les sépare (mobilité des travailleurs entre branches, rendements constants ou croissants, avantages donnés ou construits).", "Elle associe à chaque analyse une politique (ouverture, compensation des perdants, protection temporaire, diversification).", "Elle cite au moins un fait et se termine par une prise de position explicite, justifiée par un des arguments présentés."],
    corrige: P("<b>Ricardo.</b> Chaque pays gagne à se spécialiser selon son avantage comparatif, même s’il est moins productif partout. Le gain porte sur le pays entier et suppose que les travailleurs passent sans coût d’une branche à l’autre. La politique qui en découle est l’ouverture.", "<b>Heckscher, Ohlin et Samuelson.</b> Un pays exporte les biens qui utilisent le facteur dont il est bien doté. L’ouverture profite à ce facteur et nuit à l’autre. Dans un pays riche, le travail peu qualifié y perd. Le pays gagne au total, mais il y a des perdants, qu’il faudrait compenser. Les travaux de David Autor sur le « choc chinois » ont montré que ces pertes sont concentrées dans certaines régions des États-Unis et qu’elles durent.", "<b>Krugman.</b> Avec des rendements croissants, des pays semblables gagnent à échanger des variétés d’un même produit. Les gains sont partagés, mais l’avantage peut tenir à l’histoire, et la production se concentre là où elle est déjà installée. Les entreprises les moins productives disparaissent et leurs salariés doivent se reconvertir. La politique qui en découle est l’ouverture entre pays semblables, accompagnée d’un soutien à la reconversion.", "<b>List et Chang.</b> Les avantages comparatifs se construisent. Un pays en retard doit protéger un temps ses industries naissantes, comme l’ont fait les États-Unis et l’Allemagne au XIXe siècle, puis la Corée du Sud. L’hypothèse contestée est celle d’avantages donnés une fois pour toutes.", "<b>Prebisch et Singer.</b> Selon eux, les prix des matières premières tendent à baisser par rapport à ceux des produits manufacturés. Les pays qui en dépendent voient leurs termes de l’échange se dégrader et doivent se diversifier.", "<b>Prise de position possible.</b> L’ouverture augmente le revenu total, ce que suggèrent les replis commerciaux du passé, comme le tarif américain de 1930, même si son rôle exact dans la crise reste discuté. Mais ses gains sont diffus et ses pertes concentrées, et la compensation promise aux perdants a rarement eu lieu. Dani Rodrik en conclut qu’une ouverture durable suppose de laisser aux États des marges pour protéger leurs choix sociaux. Une ouverture assortie de politiques actives pour les régions touchées paraît mieux fondée qu’un retour général au protectionnisme, dont les consommateurs paient le prix.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
